import os

print('CWD:', os.getcwd())
for root, dirs, files in os.walk('.'):
    depth = root.count(os.sep)
    if depth > 3:
        dirs[:] = []
        continue
    for f in files:
        if f.endswith(('.xlsx', '.xls', '.csv', '.tsv')):
            print(os.path.join(root, f))

